<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_login();
$rows=$conn->query("SELECT dc.*,d.name,d.phone,c.car_name,c.plate_number,cs.sale_date FROM dalali_commissions dc JOIN dalalis d ON d.id=dc.dalali_id JOIN cars c ON c.id=dc.car_id JOIN car_sales cs ON cs.id=dc.sale_id ORDER BY dc.status='PENDING' DESC,cs.sale_date DESC");$pending=0;$paid=0;$data=[];while($r=$rows->fetch_assoc()){if($r['status']==='PENDING')$pending+=(float)$r['amount'];if($r['status']==='PAID')$paid+=(float)$r['amount'];$data[]=$r;}
$page_title='Dalali Commissions';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><div class="report-title"><div><h1 class="page-title">Dalali Commission Report</h1><p class="muted">Accrued and paid agent commissions linked to actual vehicle sales.</p></div><button class="btn" onclick="window.print()">Print</button></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))"><div class="card"><p>Pending Commission</p><h2><?=money($pending)?></h2></div><div class="card"><p>Paid Commission</p><h2><?=money($paid)?></h2></div></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Sale Date</th><th>Dalali</th><th>Phone</th><th>Car</th><th>Amount</th><th>Status</th><th>Paid Date</th><th>Method / Ref</th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=e($r['sale_date'])?></td><td><?=e($r['name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['car_name'].' / '.car_sales_plate_label($r['plate_number']))?></td><td><?=money($r['amount'])?></td><td><?=e($r['status'])?></td><td><?=e($r['paid_date']?:'—')?></td><td><?=e($r['payment_method']?:'—')?><?php if($r['payment_reference']):?><br><small><?=e($r['payment_reference'])?></small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php include __DIR__.'/../includes/footer.php';?>
